item.aggregated_output:
/**
 * Consumer views, version 1: the small shapes a patient-facing chart app reads.
 *
 * These are defined by the consumer, not by any source. A mapper turns one source's FOLIO record items
 * for one patient into these rows. The consumer merges rows from several sources itself, so a mapper
 * reports only what its own source says, and never invents, infers from other sources, or "corrects"
 * what the source records.
 *
 * Contract (see `Transform`): the mapper receives every item one source published for one patient,
 * in no particular order and including items that were later superseded or retracted, plus an
 * `asOf` date. It returns the rows that describe that source's record as it stood at the end of that
 * date.
 *
 * Conventions for every view:
 *
 * - **Scope in time.** An item is in scope when its envelope `recorded` time is on or before the end of
 *   the `asOf` day in America/Chicago. Ignore items recorded later. Apply the FOLIO correction rules to
 *   the items in scope: an item listed in another in-scope item's `supersedes` or `retracts` (same
 *   issuer) is not current; supersession is transitive. Use only current items, except where a view
 *   below says otherwise.
 * - **Time zone.** The consumer displays everything in America/Chicago. "Local date" and "local time"
 *   below mean wall-clock date/time in America/Chicago (UTC-6 standard, UTC-5 daylight time).
 * - **Partial dates.** `PartialDate` strings keep the precision the source actually knows: "2016"
 *   means some time in 2016, never 2016-01-01. Never pad a year-only or month-only date.
 * - **Only what the source records.** Rows come from structured payload entries. Narrative text may be
 *   used to understand an entry but must not be the only basis for a row.
 * - **Evidence.** Every row lists the items (and payload entry ids) it was built from, so the consumer
 *   can show the source text behind a fact.
 * - **Determinism.** Same input, same output: no clock, randomness, network or file access.
 */

/** A FOLIO record item in its JSON form (see the FOLIO record-item spec). */
export interface FolioItem {
  folio: string;
  /** Item id (ULID), unique within the issuer. */
  id: string;
  /** did:web of the issuing organization. */
  issuer: string;
  /** Patient id at this issuer. */
  patient: string;
  /** When the clinical event happened: RFC 3339 date-time with offset, or a full or partial date. */
  effective: string;
  effective_end?: string;
  /** When the issuer committed this item: RFC 3339 date-time with offset. */
  recorded: string;
  author?: { id?: string; name?: string; role?: string };
  /** The payload's schema: `type` names the entry type in the source's .d.ts. */
  schema?: { url: string; type: string; sha256: string };
  /** Ids of earlier items from the same issuer that this item replaces entirely. */
  supersedes?: string[];
  /** Ids of earlier items from the same issuer that were entered in error, withdrawn without replacement. */
  retracts?: string[];
  /** Markdown narrative with `<ref id="…">…</ref>` spans; "" if none. */
  narrative: string;
  /** Entry id -> entry, each entry typed by the source's schema; {} if none. */
  payload: Record<string, any>;
}

/** The mapper's entry point. `asOf` is a local date, `YYYY-MM-DD`. */
export type Transform = (items: FolioItem[], asOf: string) => ViewRows;

/** Everything one mapper returns for one patient and one source. Empty arrays where the source has nothing. */
export interface ViewRows {
  medications: MedicationRow[];
  problems: ProblemRow[];
  allergies: AllergyIntoleranceRow[];
  labs: LabResultRow[];
  vitals: VitalRow[];
}

/** `YYYY`, `YYYY-MM` or `YYYY-MM-DD`; the precision is the string's length. */
export type PartialDate = string;

/** The items (and entries inside them) a row was built from. At least one. */
export type Evidence = { item_id: string; entry_id?: string }[];

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Medications
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One outpatient (home) medication as this source records it, with its status as of `asOf`.
 *
 * - One row per drug ingredient. If the source has several lines, orders or prescriptions for the
 *   same ingredient over time (stopped and restarted, re-entered), report the most recent one, i.e.
 *   the one whose own latest event is latest. A line or order that was entered in error, voided or
 *   retracted never existed: do not report it, and do not let it affect another line.
 * - Include medications that are stopped (status 'stopped') if the source still shows them, so the
 *   consumer can say what was stopped and why.
 * - Exclude hospital-only orders (infusions, IV fluids, inpatient-only drugs). They are not home
 *   medications.
 * - When the source publishes a medication list as repeated snapshots (each document or save restates
 *   the list), the latest in-scope snapshot is the source's list; a drug missing from the latest
 *   snapshot is not reported. When the source publishes events or status rows, the latest event or
 *   status row for a line determines its state, however old it is.
 */
export interface MedicationRow {
  /**
   * Generic ingredient name, lower case, without salt or form: "losartan" (not "losartan potassium"),
   * "metformin", "insulin glargine", "empagliflozin". Translate brand names the record uses
   * ("Jardiance" -> "empagliflozin"). Omit only when the record does not say which drug it is (e.g. the
   * patient wrote "water pill").
   */
  ingredient?: string;
  /** RxNorm ingredient CUI, only when the source states an ingredient-level RxNorm code. Never guessed or derived from a product code. */
  rxnorm_ingredient?: string;
  /** The drug as the source names it (display text), e.g. "losartan potassium 50 MG Oral Tablet" or "Jardiance". */
  drug_name: string;
  /**
   * Status as of `asOf`, by this source's account.
   * - 'active': the patient should be taking it (or, on a patient's own list, says they are).
   * - 'held': paused with intent (or at least possibility) of resuming; the patient should not be
   *   taking it now. Not the same as stopped.
   * - 'stopped': discontinued.
   * - 'unknown': the source lists the drug but records no decision about whether it is being taken
   *   (e.g. a hospital list marked as not reconciled).
   */
  status: 'active' | 'held' | 'stopped' | 'unknown';
  /**
   * Local date on which the current status began according to this source: for 'held' or 'stopped',
   * the date of the hold or stop; for 'active', the date the source's current line or order started
   * (or resumed). Keep the source's precision. Omit if the source does not say.
   */
  status_since?: PartialDate;
  /**
   * Amount per administration currently prescribed (for 'held' and 'stopped': the amount when it was
   * held or stopped). For a patient's own list: the amount the patient says they take, if they give
   * one. `unit` is one of the listed units; convert source spellings ("unit", "UNT", "[iU]" ->
   * "units"; "tab"/"tablets" -> "tablet"). Omit when the source gives no single amount.
   */
  dose?: { value: number; unit: 'mg' | 'mcg' | 'units' | 'mL' | 'tablet' };
  /**
   * How often, normalized: 'QD' once daily, 'BID' twice daily, 'TID' three times daily, 'QHS' once
   * daily at bedtime, 'QW' once weekly, 'PRN' as needed, 'other' anything else. Omit if unknown.
   */
  frequency?: 'QD' | 'BID' | 'TID' | 'QHS' | 'QW' | 'PRN' | 'other';
  /**
   * For 'stopped' rows, why, when the source records a coded or clearly stated reason:
   * - 'adverse_reaction': side effect or adverse reaction.
   * - 'ineffective': not working well enough.
   * - 'therapy_changed': replaced by another drug for the same purpose.
   * - 'course_complete': finite course finished.
   * - 'patient_choice': the patient declined or asked to stop.
   * - 'other': another reason (see `status_reason_text`).
   * Omit when the source gives no reason, and on rows that are not 'stopped'.
   */
  stop_reason?: 'adverse_reaction' | 'ineffective' | 'therapy_changed' | 'course_complete' | 'patient_choice' | 'other';
  /** Free-text reason for the current status (hold or stop) as the source wrote it, if any. */
  status_reason_text?: string;
  /** True when the row comes from the patient's own account (a self-reported list), not a clinician's record. */
  patient_reported: boolean;
  /** True when the source says the drug was bought without a prescription. Omit otherwise. */
  otc?: boolean;
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Problems
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One condition on the source's problem list (or the source's equivalent: its diagnosis or history
 * lists), with status as of `asOf`.
 *
 * - One row per condition. Several entries for the same condition (re-listed in several documents,
 *   restaged, re-coded) are one row whose fields reflect the latest entry.
 * - Report only conditions the source asserts the patient has or had. Never report a condition that
 *   was ruled out, or one that was only suspected (working/provisional) and never confirmed.
 * - Billing codes attached to a visit or claim are not problem-list entries, unless the source says
 *   its problem list is built from them.
 * - An adverse effect of a drug (however the source records it, including as an ICD-10 T-code
 *   diagnosis) is an `AllergyIntoleranceRow` of type 'adverse_reaction', not a problem. The illness it
 *   caused (e.g. ketoacidosis) is still a problem.
 */
export interface ProblemRow {
  /** The condition as the source words it, e.g. "Chronic kidney disease stage 3a". */
  condition: string;
  /** ICD-10-CM code, with the dot, as the source gives it (latest). Omit if the source gives none. */
  icd10cm?: string;
  /** SNOMED CT concept id, if the source gives one. */
  snomed?: string;
  /**
   * - 'active': the patient has it.
   * - 'resolved': the patient had it and the source says it is resolved or historical.
   */
  status: 'active' | 'resolved';
  /** When the condition began, at the precision the source knows. Omit if the source does not say. */
  onset?: { value: PartialDate; precision: 'year' | 'month' | 'day' };
  /**
   * For chronic kidney disease only: the KDIGO GFR category the source most recently recorded for this
   * patient ('G3a' for "stage 3a", "N18.31" or a G3a category field). As recorded by a clinician; never
   * computed from lab values.
   */
  ckd_stage?: 'G1' | 'G2' | 'G3a' | 'G3b' | 'G4' | 'G5';
  /** For chronic kidney disease only: KDIGO albuminuria category as recorded ('A1', 'A2', 'A3'), if the source records one. */
  albuminuria?: 'A1' | 'A2' | 'A3';
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Allergies, intolerances, adverse reactions
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One substance the patient should avoid or be careful with, as of `asOf`. Only current entries: an
 * entry the source marks inactive or invalid is not reported. "No known drug allergies" is not a row.
 */
export interface AllergyIntoleranceRow {
  /** Substance: generic ingredient name, lower case, for drugs ("lisinopril"); as written otherwise. */
  substance: string;
  /** RxNorm ingredient CUI, if the source gives one. */
  rxnorm_ingredient?: string;
  /**
   * What kind of reaction, by its nature (not by which list the source keeps it on):
   * - 'allergy': immune-mediated (hives, rash, angioedema, anaphylaxis, bronchospasm).
   * - 'intolerance': a non-immune, predictable side effect that made the drug unacceptable (e.g.
   *   ACE-inhibitor cough, GI upset).
   * - 'adverse_reaction': a serious harmful event attributed to the drug that is not an allergy (e.g.
   *   drug-associated ketoacidosis, lactic acidosis).
   * If the source keeps all three on one undifferentiated list, decide from the recorded reaction.
   */
  type: 'allergy' | 'intolerance' | 'adverse_reaction';
  /** Reaction(s) as the source words them, joined with "; ". Omit if not recorded. */
  reaction?: string;
  /**
   * Criticality: how dangerous re-exposure is judged to be.
   * - 'high': re-exposure could be serious or life-threatening.
   * - 'low': re-exposure unlikely to cause serious harm.
   * - 'unknown': not assessed or not derivable.
   * A source's "severity" scale is mapped by meaning: mild -> 'low'; severe or life-threatening -> 'high'.
   */
  criticality: 'low' | 'high' | 'unknown';
  /** When the reaction began, at the precision the source knows. */
  onset?: { value: PartialDate; precision: 'year' | 'month' | 'day' };
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Lab results
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Analytes this consumer tracks, with the unit `LabResultRow.value` must be in. Results for other
 * tests are not reported.
 *
 * | analyte         | unit            | notes |
 * |-----------------|-----------------|-------|
 * | creatinine      | mg/dL           | serum |
 * | egfr            | mL/min/1.73m2   | see `egfr_equation` and the eGFR rule below |
 * | potassium       | mmol/L          | |
 * | sodium          | mmol/L          | |
 * | chloride        | mmol/L          | |
 * | bicarbonate     | mmol/L          | total CO2 |
 * | anion_gap       | mmol/L          | |
 * | bun             | mg/dL           | urea nitrogen |
 * | glucose         | mg/dL           | laboratory glucose (serum/plasma); home meter readings are vitals |
 * | a1c             | %               | NGSP |
 * | uacr            | mg/g            | urine albumin/creatinine ratio |
 * | platelets       | 10*3/uL         | thousands per microlitre: 212 000 cells/uL is 212 |
 * | wbc             | 10*3/uL         | thousands per microlitre |
 * | hemoglobin      | g/dL            | |
 * | bhb             | mmol/L          | beta-hydroxybutyrate |
 * | ph              | [pH]            | blood gas pH |
 * | pco2            | mmHg            | |
 * | lipase          | U/L             | |
 * | troponin        | ng/mL           | troponin I |
 * | cholesterol     | mg/dL           | total |
 * | triglycerides   | mg/dL           | |
 * | hdl             | mg/dL           | |
 * | ldl             | mg/dL           | measured or calculated |
 */
export type Analyte =
  | 'creatinine' | 'egfr' | 'potassium' | 'sodium' | 'chloride' | 'bicarbonate' | 'anion_gap' | 'bun'
  | 'glucose' | 'a1c' | 'uacr' | 'platelets' | 'wbc' | 'hemoglobin' | 'bhb' | 'ph' | 'pco2' | 'lipase'
  | 'troponin' | 'cholesterol' | 'triglycerides' | 'hdl' | 'ldl';

/**
 * One valid laboratory result.
 *
 * - One row per result. A result the source shows several times (copies in several documents, a
 *   preliminary and a final copy) is one row, taken from the copy with the most advanced status.
 * - Report only values that stand: leave out results that were withdrawn, invalidated or "corrected
 *   away" by the lab, results of orders voided or entered in error, results not performed, and
 *   superseded copies. A confirmation repeat is a second valid result; keep both.
 * - **eGFR rule.** One eGFR row per eGFR calculation the source reports for a specimen. When the source
 *   reports race-specific variants of one calculation (a value with and one without a race
 *   coefficient), report only the variant without the race coefficient. Report the value as printed
 *   (do not recompute).
 */
export interface LabResultRow {
  analyte: Analyte;
  /** Numeric value in the analyte's unit (see `Analyte`). For a result printed with a comparator (">60", "<0.01"), the number part. */
  value: number;
  /** Set when the printed result has a comparator: ">60" -> value 60, comparator '>'. */
  comparator?: '<' | '>' | '<=' | '>=';
  /** The analyte's unit from the table in `Analyte`, exactly as written there. */
  unit: string;
  /** Specimen collection time, RFC 3339 with offset (any offset; it denotes an instant). */
  collected: string;
  /** 'final' (also for amended or corrected values that stand) or 'preliminary'. */
  status: 'final' | 'preliminary';
  /**
   * For analyte 'egfr' only: the equation the source says it used.
   * - 'ckd-epi-2021': CKD-EPI 2021 (race-free).
   * - 'ckd-epi-2009': CKD-EPI 2009.
   * - 'mdrd': MDRD.
   * - 'unknown': not stated.
   * When a code and a method note disagree, believe the method note.
   */
  egfr_equation?: 'ckd-epi-2021' | 'ckd-epi-2009' | 'mdrd' | 'unknown';
  /** LOINC code if the source gives one for this result. */
  loinc?: string;
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Vital signs and home readings
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One set of vital signs taken together, or one home reading.
 *
 * - A clinic or hospital vital-sign set (BP, pulse, weight taken within a few minutes at one visit) is
 *   one row; `local_time` is the time of its first blood pressure (or of its first measurement if no
 *   BP). A repeat blood pressure taken later in the same visit goes in `repeat_*` on the same row.
 * - Each home BP reading and each home glucose reading is its own row.
 * - Each measurement is reported once: if a source shows the same measurement twice (a reading typed
 *   in by hand that duplicates one synced from the device a minute or two earlier with the same
 *   values), report it once, preferring the device copy.
 */
export interface VitalRow {
  /** 'clinic' (outpatient office), 'hospital' (ED or inpatient), or 'home' (patient's own devices). */
  setting: 'clinic' | 'hospital' | 'home';
  /** Local wall-clock time in America/Chicago, `YYYY-MM-DDTHH:MM`. */
  local_time: string;
  systolic_mmhg?: number;
  diastolic_mmhg?: number;
  /** Repeat blood pressure at the same visit, if one was taken. */
  repeat_systolic_mmhg?: number;
  repeat_diastolic_mmhg?: number;
  pulse_bpm?: number;
  /** Body weight in kilograms (1 lb = 0.45359237 kg), one decimal place. */
  weight_kg?: number;
  /** Home glucose meter reading in mg/dL (1 mmol/L = 18.016 mg/dL), rounded to a whole number. */
  glucose_mg_dl?: number;
  /** Set when the meter showed HI or LO instead of a number; `glucose_mg_dl` is then the meter's limit in mg/dL. */
  glucose_out_of_range?: 'HI' | 'LO';
  evidence: Evidence;
}

/**
 * Lakeview Labs & Kidney Care: FOLIO export, version 1.
 *
 * Lakeview runs an outreach reference laboratory and a nephrology clinic on one system. The export is a
 * row-for-row copy of that system's tables. Every payload entry is one table row; its `type` is the table
 * name. Column names are the database's own (UPPER_SNAKE). Codes are Lakeview's, documented below; the
 * tables at the end of this file list every code value in use.
 *
 * Two kinds of item, each with its own entry type:
 *
 * - **Lab report items** (`LabReportRow`): one item per requisition, i.e. one set of specimens drawn at
 *   one time for one ordering client. Holds exactly one LAB_REQ row, one LAB_ORDER row per ordered test,
 *   and the LAB_RESULT rows those orders produced. Published when every order on the requisition is
 *   resulted, cancelled or void (rarely earlier, with 'P' rows, when a slow test holds up a requisition
 *   with urgent results). Lab items have no author (system-generated) and no narrative.
 * - **Clinic contact items** (`ClinicRow`): one item per nephrology clinic contact (office visit or
 *   telephone contact). Holds exactly one CLINIC_VISIT row plus the VISIT_DX, VITAL, MED_ORDER and
 *   MED_STATUS_HIST rows entered during that contact. The narrative is the note the nephrologist typed
 *   and signed; it is short and is never generated from the rows.
 *
 * Changes: rows are never edited in place in the export. When a row changes after its item was
 * published (a result invalidated, an order marked entered in error), Lakeview publishes a new item that
 * `supersedes` the old one and restates every row of the requisition or contact with current values.
 * Exception: a medication's status changes are separate MED_STATUS_HIST rows in a later contact, not a
 * re-published MED_ORDER row. See MED_ORDER.MED_STATUS.
 *
 * Times: every timestamp column is RFC 3339 with the UTC offset in effect in America/Chicago at that
 * moment (e.g. `2026-02-09T08:14:00-06:00`). Date-only columns are local calendar dates.
 *
 * Identifiers: REQ_ID, ORDER_ID, RESULT_ID, ACCESSION, VISIT_ID, RX_ID and HIST_ID are Lakeview-assigned,
 * never reused, and unique across the whole export (not only within an item). Rows refer to rows in
 * other items by these ids.
 */

// ─────────────────────────────────────────────────────────────────────────────────────────────────────
// Lab report items
// ─────────────────────────────────────────────────────────────────────────────────────────────────────

/** One row in a lab report item. */
export type LabReportRow = LabReq | LabOrder | LabResult;

/** The requisition: who ordered, when the specimens were drawn. Exactly one per lab report item. */
export interface LabReq {
  type: 'LAB_REQ';

  /** Requisition id, e.g. "RQ-2602090412". */
  REQ_ID: string;

  /**
   * Ordering client account code. Clients are practices that send work to Lakeview.
   * - 'NGFM': Northgate Family Medicine (outside primary care practice).
   * - 'LVNEPH': Lakeview's own nephrology clinic.
   * Other client codes exist for other patients; CLIENT_NAME always carries the display name.
   */
  CLIENT_CODE: string;

  /** Display name of the ordering client, as on the requisition. */
  CLIENT_NAME: string;

  /** NPI of the ordering clinician, 10 digits. Absent when the requisition was standing-order only. */
  ORDERING_NPI?: string;

  /** Ordering clinician's name, "Last, First Credential", as typed on the requisition. */
  ORDERING_NAME?: string;

  /**
   * When the specimens were drawn. This is the clinically meaningful time and the item's `effective`.
   * All specimens on one requisition share it.
   */
  COLLECTED_AT: string;

  /** When the specimens were logged in at the laboratory. */
  RECEIVED_AT: string;

  /**
   * Patient-reported fasting status at draw.
   * - 'Y': fasting at least 8 hours.
   * - 'N': not fasting.
   * - 'U': not asked or not recorded.
   */
  FASTING: 'Y' | 'N' | 'U';
}

/**
 * One ordered test or panel on the requisition. One row per order, even when two orders are run on the
 * same tube (they then share an ACCESSION).
 */
export interface LabOrder {
  type: 'LAB_ORDER';

  /** Order id, e.g. "OR-7730412". */
  ORDER_ID: string;

  /** The LAB_REQ this order belongs to (always the LAB_REQ in the same item). */
  REQ_ID: string;

  /**
   * What was ordered: a Lakeview test code (see `LabTestCode` at the end of this file). An order code
   * may produce several result rows: panel codes (e.g. 'LK-CBC') produce one row per component, and
   * 'LK-CREAT' also produces calculated eGFR rows.
   */
  ORDER_CODE: `${LabTestCode}`;

  /** Display name of the ordered test as printed on the requisition. */
  ORDER_NAME: string;

  /**
   * Specimen container barcode, "LV" + 2-digit year, day of year, 5-digit sequence, e.g. "LV26-040-00093".
   * One accession per tube; several orders can share one. Outside systems that receive Lakeview results
   * (e.g. Northgate) keep this number as their link back to Lakeview.
   */
  ACCESSION: string;

  /**
   * Specimen type.
   * - 'SER': serum.
   * - 'PLA': plasma (lithium heparin).
   * - 'WB': whole blood (EDTA).
   * - 'URN': random urine.
   */
  SPECIMEN_TYPE: 'SER' | 'PLA' | 'WB' | 'URN';

  /**
   * Specimen condition noted on receipt or by the analyzer.
   * - 'OK': acceptable.
   * - 'HEM': hemolyzed. Potassium, AST and LDH can be falsely high. Results are still released, with a
   *   comment; a recollection is usually requested.
   * - 'LIP': lipemic.
   * - 'ICT': icteric.
   * - 'QNS': quantity not sufficient; affected results have RESULT_STATUS 'X'.
   * - 'CLT': clotted.
   */
  SPECIMEN_COND: 'OK' | 'HEM' | 'LIP' | 'ICT' | 'QNS' | 'CLT';

  /**
   * Where the order stands in the lab workflow. Integer code. This is a separate axis from each result
   * row's RESULT_STATUS: an order is 4 (resulted) as soon as its results have been released, and stays 4
   * even if one of its results is later invalidated (RESULT_STATUS 'C'). Never infer result validity from
   * this field.
   * - 1: ordered, not yet collected.
   * - 2: collected, in transit or awaiting testing.
   * - 3: in process (some results may be preliminary).
   * - 4: resulted (results released).
   * - 5: cancelled before testing (no results; see STATUS_REASON).
   * - 9: entered in error (wrong patient, duplicate order). The order is void. Any result rows it has
   *      were produced by the analyzer before the error was caught, still carry their own
   *      RESULT_STATUS (often 'F'), and must not be used.
   */
  ORDER_STATUS: 1 | 2 | 3 | 4 | 5 | 9;

  /** When ORDER_STATUS last changed. */
  STATUS_AT: string;

  /** Free-text reason entered with status 5 or 9, e.g. "Duplicate order". Absent for other statuses. */
  STATUS_REASON?: string;

  /**
   * Set when this order is a repeat draw of an earlier order (in an earlier requisition): that order's
   * ORDER_ID. Absent for ordinary orders.
   */
  REPEAT_OF_ORDER_ID?: string;

  /**
   * Why the repeat draw was taken. Present exactly when REPEAT_OF_ORDER_ID is.
   * - 'HEM': the earlier specimen was hemolyzed. The earlier result is normally invalidated
   *   (RESULT_STATUS 'C', REPLACED_BY_RESULT_ID pointing here).
   * - 'CONF': confirmation of a critical or unexpected value. Both results stand; the earlier one is
   *   NOT invalidated.
   * - 'QNS': the earlier specimen was insufficient.
   */
  REPEAT_REASON?: 'HEM' | 'CONF' | 'QNS';
}

/**
 * One reported result value. Lakeview stores every result as text (VALUE_TEXT) plus a numeric
 * convenience column (VALUE_NUM). VALUE_TEXT is the value of record.
 */
export interface LabResult {
  type: 'LAB_RESULT';

  /** Result id, e.g. "RS-90044817". */
  RESULT_ID: string;

  /** The LAB_ORDER that produced this row (always in the same item). */
  ORDER_ID: string;

  /**
   * Lakeview test code for this result (see `LabTestCode`). Codes are stable across years but are
   * retired and replaced when the method or equation changes: eGFR changed code on 2022-01-10. A
   * mapper that needs a continuous series must join the old and new codes.
   */
  TEST_CODE: `${LabTestCode}`;

  /** Test name as printed on the report on the day it was resulted. Wording varies over the years. */
  TEST_NAME: string;

  /**
   * LOINC code, copied from Lakeview's code table at the moment the row was resulted. Absent when the
   * test code had no LOINC mapping at that moment, which includes some codes that are mapped now (rows
   * resulted before the mapping was added are not back-filled). `LabTestCode` says which codes
   * have a mapping and since when. Do not use LOINC as the only key to find a test; use TEST_CODE.
   */
  LOINC?: string;

  /**
   * The result as reported, as text. Usually a plain decimal ("1.45", "212"). May carry a comparator
   * (">60", "<0.1", ">90") or be non-numeric ("Not done: QNS", "See comment"). Never sort or compare as
   * text.
   */
  VALUE_TEXT: string;

  /**
   * Numeric form of VALUE_TEXT, for queries.
   * - A number when VALUE_TEXT is a plain decimal: the same value.
   * - 9999999 (sentinel) when VALUE_TEXT has a comparator such as ">60": the number is NOT the value;
   *   read VALUE_TEXT.
   * - null when VALUE_TEXT is not numeric.
   */
  VALUE_NUM: number | null;

  /**
   * Unit of VALUE_TEXT, as Lakeview prints it (see `LakeviewUnit`). Fixed per TEST_CODE. Null only when
   * VALUE_TEXT is not numeric. Note 'K/uL' means thousands per microlitre: a platelet count of "212" is
   * 212 000 cells/uL.
   */
  UNIT_CODE: `${LakeviewUnit}` | null;

  /** Reference interval as printed, e.g. "3.5-5.1", "<30", ">59". Text; may be absent for calculated tests. */
  REF_RANGE_TEXT?: string;

  /**
   * Abnormal flag against the reference interval.
   * - 'N': within range.
   * - 'L' / 'H': below / above range.
   * - 'LL' / 'HH': critical low / high (phoned to the ordering clinician).
   * - 'A': abnormal, non-numeric.
   * Absent when the test has no reference interval or the value is not numeric.
   */
  ABN_FLAG?: 'N' | 'L' | 'H' | 'LL' | 'HH' | 'A';

  /**
   * Validity of this row's value. Letter code. Independent of the order's ORDER_STATUS.
   * - 'P': preliminary; a later item will restate the row as 'F'.
   * - 'F': final.
   * - 'A': amended; the value on this row was changed after it was final (for example a transcription
   *   fix). The value shown is the current, valid one; the earlier value is in the superseded item.
   * - 'C': corrected away. The value on this row has been withdrawn and must not be used. If a
   *   replacement exists, REPLACED_BY_RESULT_ID names it (usually in a repeat-draw requisition). Note:
   *   this is NOT the HL7 v2 meaning of 'C' (where 'C' marks the new corrected value); in Lakeview 'C'
   *   marks the old, withdrawn one.
   * - 'X': not performed (cancelled, QNS); VALUE_TEXT says why, VALUE_NUM is null.
   */
  RESULT_STATUS: 'P' | 'F' | 'A' | 'C' | 'X';

  /** When the value was released (first released, for 'A' and 'C' rows). */
  RESULTED_AT: string;

  /** When RESULT_STATUS was set to 'A' or 'C'. Absent otherwise. */
  STATUS_CHANGED_AT?: string;

  /** For RESULT_STATUS 'C': the RESULT_ID of the row that replaces this one. Absent if no replacement. */
  REPLACED_BY_RESULT_ID?: string;

  /**
   * For calculated results: the RESULT_ID of the row it was calculated from (same item): the
   * creatinine row for eGFR, the total cholesterol row for calculated LDL (LK-LDLC).
   * Lakeview calculates eGFR from creatinine, the patient's age and sex on the collection date, and,
   * for the 2009 codes only, a race coefficient (both race variants are always reported; the lab
   * does not know the patient's race).
   */
  DERIVED_FROM_RESULT_ID?: string;

  /** Result comment as printed on the report, free text. Lakeview's comments are canned phrases. */
  COMMENT_TEXT?: string;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────────
// Clinic contact items
// ─────────────────────────────────────────────────────────────────────────────────────────────────────

/** One row in a nephrology clinic contact item. */
export type ClinicRow = ClinicVisit | VisitDx | Vital | MedOrder | MedStatusHist;

/** The clinic contact itself. Exactly one per clinic contact item. */
export interface ClinicVisit {
  type: 'CLINIC_VISIT';

  /** Contact id, e.g. "NV-104552". */
  VISIT_ID: string;

  /**
   * Kind of contact.
   * - 'NP': new patient office visit.
   * - 'FU': follow-up office visit.
   * - 'TEL': telephone contact (no vitals; CKD_G / CKD_A usually absent).
   */
  VISIT_TYPE: 'NP' | 'FU' | 'TEL';

  /** Start of the contact. The item's `effective`. */
  VISIT_AT: string;

  /** NPI of the nephrologist responsible for the contact. */
  PROVIDER_NPI: string;

  /**
   * KDIGO GFR category as assessed by the nephrologist at this contact: 'G1', 'G2', 'G3a', 'G3b',
   * 'G4', 'G5'. A clinician judgement (usually from two or more eGFRs ≥ 90 days apart), not computed
   * from a single lab value. Absent when not assessed at this contact.
   */
  CKD_G?: 'G1' | 'G2' | 'G3a' | 'G3b' | 'G4' | 'G5';

  /**
   * KDIGO albuminuria category as assessed at this contact: 'A1' (UACR < 30 mg/g), 'A2' (30–300),
   * 'A3' (> 300). Absent when not assessed.
   */
  CKD_A?: 'A1' | 'A2' | 'A3';

  /** Referring practice as typed at registration, free text. Present on 'NP' visits from a referral. */
  REFERRED_BY_TEXT?: string;
}

/** One diagnosis recorded at the contact. The clinic's problem list is the latest VISIT_DX row per code. */
export interface VisitDx {
  type: 'VISIT_DX';

  /** The contact (same item). */
  VISIT_ID: string;

  /** Order of importance at this contact, 1 = primary. */
  DX_RANK: number;

  /** ICD-10-CM code, with the dot (e.g. "N18.32"). Always present. */
  ICD10CM: string;

  /** ICD-10-CM description as shown in the clinic system. */
  DX_TEXT: string;

  /**
   * - 'A': active, confirmed.
   * - 'P': provisional / working diagnosis.
   * - 'R': ruled out at this contact. Not a diagnosis the patient has.
   * - 'H': history of; resolved, recorded for context.
   */
  DX_STATUS: 'A' | 'P' | 'R' | 'H';
}

/**
 * One vital-sign measurement taken at an office visit. Blood pressure is two rows (systolic and
 * diastolic) linked by READING_NO. Unlike lab values, vitals are stored as numbers.
 */
export interface Vital {
  type: 'VITAL';

  /** The contact (same item). */
  VISIT_ID: string;

  /**
   * - 'BPS': systolic blood pressure, mmHg.
   * - 'BPD': diastolic blood pressure, mmHg.
   * - 'HR': heart rate, /min.
   * - 'WT': weight, kg.
   */
  VITAL_CODE: 'BPS' | 'BPD' | 'HR' | 'WT';

  /** The measurement, in UNIT_CODE. */
  VALUE_NUM: number;

  /** 'mmHg' for BPS/BPD, '/min' for HR, 'kg' for WT. Always present. */
  UNIT_CODE: 'mmHg' | '/min' | 'kg';

  /** 1 for the first reading of this VITAL_CODE at the contact, 2 for a repeat, and so on. */
  READING_NO: number;

  /** When the measurement was taken. */
  TAKEN_AT: string;
}

/**
 * A medication prescribed or managed by the nephrology clinic, as the row stood when this item was
 * published. The clinic records only medications it prescribes or changes; it does not keep a full home
 * medication list.
 */
export interface MedOrder {
  type: 'MED_ORDER';

  /** Prescription id, e.g. "RX-30418". Stable for the life of the prescription. */
  RX_ID: string;

  /** The contact at which it was prescribed (same item). */
  VISIT_ID: string;

  /** Lakeview formulary id, e.g. "LVD-04471". Always present; stable across years. */
  LV_DRUG_ID: string;

  /** Drug name and strength from the Lakeview formulary, e.g. "finerenone 10 mg tablet". */
  DRUG_NAME: string;

  /**
   * RxNorm CUI (SCD or SBD) from the formulary. Absent for drugs added to the formulary locally without
   * a mapping; recent additions often have none. Identify the drug by LV_DRUG_ID and DRUG_NAME.
   */
  RXNORM?: string;

  /** Dose per administration, as a number. */
  DOSE_QTY: number;

  /** Unit of DOSE_QTY: 'mg', 'mcg', 'unit', 'mL'. */
  DOSE_UNIT: 'mg' | 'mcg' | 'unit' | 'mL';

  /** 'PO' by mouth, 'SC' subcutaneous, 'IV' intravenous. */
  ROUTE: 'PO' | 'SC' | 'IV';

  /** Frequency code (see `FrequencyCode`). */
  FREQ_CODE: `${FrequencyCode}`;

  /**
   * Status when this row was published. Integer code.
   * - 1: active (patient should be taking it).
   * - 2: discontinued. Final; a restart is a new RX_ID.
   * - 3: on hold. Patient told to stop for now, with intent to resume; not being taken. Can return to 1.
   * - 9: entered in error. The prescription never existed; ignore it.
   *
   * Later changes are NOT made by re-publishing this row. They arrive as MED_STATUS_HIST rows (with the
   * same RX_ID) in later contact items. The current status is NEW_STATUS of the latest MED_STATUS_HIST row
   * for the RX_ID, or this field if there is none.
   */
  MED_STATUS: 1 | 2 | 3 | 9;

  /** Date the patient is to start. Local date. */
  START_DATE: string;

  /** NPI of the prescriber. */
  PRESCRIBER_NPI: string;
}

/** A change to the status of an existing MED_ORDER, made at this contact. */
export interface MedStatusHist {
  type: 'MED_STATUS_HIST';

  /** History row id, e.g. "MH-5520193". */
  HIST_ID: string;

  /** The contact where the change was made (same item). */
  VISIT_ID: string;

  /** The prescription changed. Its MED_ORDER row is in an earlier item. */
  RX_ID: string;

  /** Status before the change (MED_ORDER.MED_STATUS codes). */
  OLD_STATUS: 1 | 2 | 3 | 9;

  /** Status after the change (MED_ORDER.MED_STATUS codes). This is the prescription's current status until a later row. */
  NEW_STATUS: 1 | 2 | 3 | 9;

  /** When the change was made. */
  CHANGED_AT: string;

  /**
   * - 'LAB': abnormal lab result.
   * - 'ADR': adverse drug reaction.
   * - 'PT': patient request.
   * - 'PROC': upcoming procedure.
   * - 'ERR': entered in error.
   * - 'OTH': other; see COMMENT_TEXT.
   */
  REASON_CODE: 'LAB' | 'ADR' | 'PT' | 'PROC' | 'ERR' | 'OTH';

  /** For NEW_STATUS 3: date the clinic plans to review resuming. Local date. Absent otherwise. */
  REVIEW_DATE?: string;

  /** Short free-text comment typed with the change. */
  COMMENT_TEXT?: string;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────────
// Code tables (as of this schema version; a new code means a new schema version)
// ─────────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Lakeview lab test codes, used in LAB_ORDER.ORDER_CODE and LAB_RESULT.TEST_CODE. Each member says the
 * specimen, the unit (LAB_RESULT.UNIT_CODE), the LOINC mapping and since when it exists (rows resulted
 * before that date have no LOINC), and the years the code was in use.
 *
 * eGFR reporting rules:
 * - Until 2022-01-09, every LK-CREAT result produced two eGFR rows, LK-EGFR09N and LK-EGFR09A, for
 *   every patient. They are two calculations from the same creatinine, not two measurements; at most
 *   one applies to a given patient, and the lab does not record which.
 * - From 2022-01-10, one row, LK-EGFR21. The old codes were retired; old rows were not recalculated.
 * - Until 2021-06-30, eGFR values of 60 or more were reported as ">60" (VALUE_NUM 9999999). From
 *   2021-07-01, values are reported as numbers up to 90 and as ">90" above.
 */
export declare enum LabTestCode {
  /** Creatinine, serum. Unit mg/dL. LOINC 2160-0 (always). In use 2015–. An LK-CREAT order also produces the calculated eGFR rows. */
  LK_CREAT = 'LK-CREAT',
  /**
   * eGFR, CKD-EPI 2009 equation, non-African American value. Serum. Unit mL/min/1.73m2. In use
   * 2015–2022-01-09. LOINC 48642-3 (always). Note: that LOINC code is defined for the MDRD equation;
   * Lakeview mapped its CKD-EPI 2009 rows to the MDRD codes and never changed the mapping. The
   * equation actually used is the one in COMMENT_TEXT.
   */
  LK_EGFR09N = 'LK-EGFR09N',
  /**
   * eGFR, CKD-EPI 2009 equation, African American value (race coefficient applied). Serum. Unit
   * mL/min/1.73m2. In use 2015–2022-01-09. LOINC 48643-1 (always), which, like LK-EGFR09N's, is an
   * MDRD code; see there.
   */
  LK_EGFR09A = 'LK-EGFR09A',
  /** eGFR, CKD-EPI 2021 equation (no race term). Serum. Unit mL/min/1.73m2. No LOINC mapping. In use 2022-01-10–. */
  LK_EGFR21 = 'LK-EGFR21',
  /** Sodium, serum. Unit mmol/L. LOINC 2951-2 (always). In use 2015–. */
  LK_NA = 'LK-NA',
  /** Potassium, serum. Unit mmol/L. LOINC 2823-3 since 2023-05-01. In use 2015–. */
  LK_K = 'LK-K',
  /** Glucose, serum. Unit mg/dL. LOINC 2345-7 (always). In use 2015–. */
  LK_GLU = 'LK-GLU',
  /** Hemoglobin A1c, whole blood. Unit % (NGSP). LOINC 4548-4 (always). In use 2015–. */
  LK_A1C = 'LK-A1C',
  /** Albumin/creatinine ratio, random urine. Unit mg/g. LOINC 9318-7 since 2023-05-01. In use 2015–. */
  LK_UACR = 'LK-UACR',
  /** CBC without differential, whole blood. Order code only: produces LK-WBC, LK-HGB and LK-PLT result rows. In use 2015–. */
  LK_CBC = 'LK-CBC',
  /** White blood cell count (component of LK-CBC). Unit K/uL. LOINC 6690-2 (always). In use 2015–. */
  LK_WBC = 'LK-WBC',
  /** Hemoglobin (component of LK-CBC). Unit g/dL. LOINC 718-7 (always). In use 2015–. */
  LK_HGB = 'LK-HGB',
  /** Platelet count (component of LK-CBC). Unit K/uL. LOINC 777-3 (always). In use 2015–. */
  LK_PLT = 'LK-PLT',
  /**
   * Lipid panel, serum. Order code only: produces LK-CHOL, LK-TRIG, LK-HDL and LK-LDLC result rows.
   * In use 2015–.
   */
  LK_LIPID = 'LK-LIPID',
  /** Total cholesterol (component of LK-LIPID). Serum. Unit mg/dL. LOINC 2093-3 (always). In use 2015–. */
  LK_CHOL = 'LK-CHOL',
  /** Triglycerides (component of LK-LIPID). Serum. Unit mg/dL. LOINC 2571-8 (always). In use 2015–. */
  LK_TRIG = 'LK-TRIG',
  /** HDL cholesterol (component of LK-LIPID). Serum. Unit mg/dL. LOINC 2085-9 (always). In use 2015–. */
  LK_HDL = 'LK-HDL',
  /**
   * LDL cholesterol, calculated, not measured: total cholesterol − HDL − triglycerides/5 (Friedewald),
   * from the rows of the same panel; DERIVED_FROM_RESULT_ID names the total cholesterol row. Unit
   * mg/dL. LOINC 13457-7 (always). When triglycerides are 400 mg/dL or more the LDL is not calculated:
   * the row then has RESULT_STATUS 'X', VALUE_TEXT "Not calculated: TG >400" and VALUE_NUM null.
   * In use 2015–.
   */
  LK_LDLC = 'LK-LDLC',
}

/** Lakeview unit strings (LAB_RESULT.UNIT_CODE). Each member gives the UCUM equivalent. */
export declare enum LakeviewUnit {
  /** Milligrams per decilitre. UCUM mg/dL. */
  MG_PER_DL = 'mg/dL',
  /** Millimoles per litre. UCUM mmol/L. */
  MMOL_PER_L = 'mmol/L',
  /** Percent; for A1c, NGSP percent. UCUM %. */
  PERCENT = '%',
  /** eGFR, mL/min normalized to 1.73 m² body surface area. UCUM mL/min/{1.73_m2}. */
  ML_MIN_173M2 = 'mL/min/1.73m2',
  /** Milligrams of albumin per gram of creatinine. UCUM mg/g{creat}. */
  MG_PER_G = 'mg/g',
  /** Thousands per microlitre (WBC, platelets): "212" means 212 000 cells/uL. UCUM 10*3/uL. */
  K_PER_UL = 'K/uL',
  /** Grams per decilitre. UCUM g/dL. */
  G_PER_DL = 'g/dL',
}

/** Medication frequency codes (MED_ORDER.FREQ_CODE). */
export declare enum FrequencyCode {
  /** Once daily. */
  QD = 'QD',
  /** Twice daily. */
  BID = 'BID',
  /** Three times daily. */
  TID = 'TID',
  /** Once daily at bedtime. */
  QHS = 'QHS',
  /** Once weekly. */
  QW = 'QW',
  /** As needed. */
  PRN = 'PRN',
}

/**
 * Consumer views, version 1: the small shapes a patient-facing chart app reads.
 *
 * These are defined by the consumer, not by any source. A mapper turns one source's FOLIO record items
 * for one patient into these rows. The consumer merges rows from several sources itself, so a mapper
 * reports only what its own source says, and never invents, infers from other sources, or "corrects"
 * what the source records.
 *
 * Contract (see `Transform`): the mapper receives every item one source published for one patient,
 * in no particular order and including items that were later superseded or retracted, plus an
 * `asOf` date. It returns the rows that describe that source's record as it stood at the end of that
 * date.
 *
 * Conventions for every view:
 *
 * - **Scope in time.** An item is in scope when its envelope `recorded` time is on or before the end of
 *   the `asOf` day in America/Chicago. Ignore items recorded later. Apply the FOLIO correction rules to
 *   the items in scope: an item listed in another in-scope item's `supersedes` or `retracts` (same
 *   issuer) is not current; supersession is transitive. Use only current items, except where a view
 *   below says otherwise.
 * - **Time zone.** The consumer displays everything in America/Chicago. "Local date" and "local time"
 *   below mean wall-clock date/time in America/Chicago (UTC-6 standard, UTC-5 daylight time).
 * - **Partial dates.** `PartialDate` strings keep the precision the source actually knows: "2016"
 *   means some time in 2016, never 2016-01-01. Never pad a year-only or month-only date.
 * - **Only what the source records.** Rows come from structured payload entries. Narrative text may be
 *   used to understand an entry but must not be the only basis for a row.
 * - **Evidence.** Every row lists the items (and payload entry ids) it was built from, so the consumer
 *   can show the source text behind a fact.
 * - **Determinism.** Same input, same output: no clock, randomness, network or file access.
 */

/** A FOLIO record item in its JSON form (see the FOLIO record-item spec). */
export interface FolioItem {
  folio: string;
  /** Item id (ULID), unique within the issuer. */
  id: string;
  /** did:web of the issuing organization. */
  issuer: string;
  /** Patient id at this issuer. */
  patient: string;
  /** When the clinical event happened: RFC 3339 date-time with offset, or a full or partial date. */
  effective: string;
  effective_end?: string;
  /** When the issuer committed this item: RFC 3339 date-time with offset. */
  recorded: string;
  author?: { id?: string; name?: string; role?: string };
  /** The payload's schema: `type` names the entry type in the source's .d.ts. */
  schema?: { url: string; type: string; sha256: string };
  /** Ids of earlier items from the same issuer that this item replaces entirely. */
  supersedes?: string[];
  /** Ids of earlier items from the same issuer that were entered in error, withdrawn without replacement. */
  retracts?: string[];
  /** Markdown narrative with `<ref id="…">…</ref>` spans; "" if none. */
  narrative: string;
  /** Entry id -> entry, each entry typed by the source's schema; {} if none. */
  payload: Record<string, any>;
}

/** The mapper's entry point. `asOf` is a local date, `YYYY-MM-DD`. */
export type Transform = (items: FolioItem[], asOf: string) => ViewRows;

/** Everything one mapper returns for one patient and one source. Empty arrays where the source has nothing. */
export interface ViewRows {
  medications: MedicationRow[];
  problems: ProblemRow[];
  allergies: AllergyIntoleranceRow[];
  labs: LabResultRow[];
  vitals: VitalRow[];
}

/** `YYYY`, `YYYY-MM` or `YYYY-MM-DD`; the precision is the string's length. */
export type PartialDate = string;

/** The items (and entries inside them) a row was built from. At least one. */
export type Evidence = { item_id: string; entry_id?: string }[];

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Medications
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One outpatient (home) medication as this source records it, with its status as of `asOf`.
 *
 * - One row per drug ingredient. If the source has several lines, orders or prescriptions for the
 *   same ingredient over time (stopped and restarted, re-entered), report the most recent one, i.e.
 *   the one whose own latest event is latest. A line or order that was entered in error, voided or
 *   retracted never existed: do not report it, and do not let it affect another line.
 * - Include medications that are stopped (status 'stopped') if the source still shows them, so the
 *   consumer can say what was stopped and why.
 * - Exclude hospital-only orders (infusions, IV fluids, inpatient-only drugs). They are not home
 *   medications.
 * - When the source publishes a medication list as repeated snapshots (each document or save restates
 *   the list), the latest in-scope snapshot is the source's list; a drug missing from the latest
 *   snapshot is not reported. When the source publishes events or status rows, the latest event or
 *   status row for a line determines its state, however old it is.
 */
export interface MedicationRow {
  /**
   * Generic ingredient name, lower case, without salt or form: "losartan" (not "losartan potassium"),
   * "metformin", "insulin glargine", "empagliflozin". Translate brand names the record uses
   * ("Jardiance" -> "empagliflozin"). Omit only when the record does not say which drug it is (e.g. the
   * patient wrote "water pill").
   */
  ingredient?: string;
  /** RxNorm ingredient CUI, only when the source states an ingredient-level RxNorm code. Never guessed or derived from a product code. */
  rxnorm_ingredient?: string;
  /** The drug as the source names it (display text), e.g. "losartan potassium 50 MG Oral Tablet" or "Jardiance". */
  drug_name: string;
  /**
   * Status as of `asOf`, by this source's account.
   * - 'active': the patient should be taking it (or, on a patient's own list, says they are).
   * - 'held': paused with intent (or at least possibility) of resuming; the patient should not be
   *   taking it now. Not the same as stopped.
   * - 'stopped': discontinued.
   * - 'unknown': the source lists the drug but records no decision about whether it is being taken
   *   (e.g. a hospital list marked as not reconciled).
   */
  status: 'active' | 'held' | 'stopped' | 'unknown';
  /**
   * Local date on which the current status began according to this source: for 'held' or 'stopped',
   * the date of the hold or stop; for 'active', the date the source's current line or order started
   * (or resumed). Keep the source's precision. Omit if the source does not say.
   */
  status_since?: PartialDate;
  /**
   * Amount per administration currently prescribed (for 'held' and 'stopped': the amount when it was
   * held or stopped). For a patient's own list: the amount the patient says they take, if they give
   * one. `unit` is one of the listed units; convert source spellings ("unit", "UNT", "[iU]" ->
   * "units"; "tab"/"tablets" -> "tablet"). Omit when the source gives no single amount.
   */
  dose?: { value: number; unit: 'mg' | 'mcg' | 'units' | 'mL' | 'tablet' };
  /**
   * How often, normalized: 'QD' once daily, 'BID' twice daily, 'TID' three times daily, 'QHS' once
   * daily at bedtime, 'QW' once weekly, 'PRN' as needed, 'other' anything else. Omit if unknown.
   */
  frequency?: 'QD' | 'BID' | 'TID' | 'QHS' | 'QW' | 'PRN' | 'other';
  /**
   * For 'stopped' rows, why, when the source records a coded or clearly stated reason:
   * - 'adverse_reaction': side effect or adverse reaction.
   * - 'ineffective': not working well enough.
   * - 'therapy_changed': replaced by another drug for the same purpose.
   * - 'course_complete': finite course finished.
   * - 'patient_choice': the patient declined or asked to stop.
   * - 'other': another reason (see `status_reason_text`).
   * Omit when the source gives no reason, and on rows that are not 'stopped'.
   */
  stop_reason?: 'adverse_reaction' | 'ineffective' | 'therapy_changed' | 'course_complete' | 'patient_choice' | 'other';
  /** Free-text reason for the current status (hold or stop) as the source wrote it, if any. */
  status_reason_text?: string;
  /** True when the row comes from the patient's own account (a self-reported list), not a clinician's record. */
  patient_reported: boolean;
  /** True when the source says the drug was bought without a prescription. Omit otherwise. */
  otc?: boolean;
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Problems
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One condition on the source's problem list (or the source's equivalent: its diagnosis or history
 * lists), with status as of `asOf`.
 *
 * - One row per condition. Several entries for the same condition (re-listed in several documents,
 *   restaged, re-coded) are one row whose fields reflect the latest entry.
 * - Report only conditions the source asserts the patient has or had. Never report a condition that
 *   was ruled out, or one that was only suspected (working/provisional) and never confirmed.
 * - Billing codes attached to a visit or claim are not problem-list entries, unless the source says
 *   its problem list is built from them.
 * - An adverse effect of a drug (however the source records it, including as an ICD-10 T-code
 *   diagnosis) is an `AllergyIntoleranceRow` of type 'adverse_reaction', not a problem. The illness it
 *   caused (e.g. ketoacidosis) is still a problem.
 */
export interface ProblemRow {
  /** The condition as the source words it, e.g. "Chronic kidney disease stage 3a". */
  condition: string;
  /** ICD-10-CM code, with the dot, as the source gives it (latest). Omit if the source gives none. */
  icd10cm?: string;
  /** SNOMED CT concept id, if the source gives one. */
  snomed?: string;
  /**
   * - 'active': the patient has it.
   * - 'resolved': the patient had it and the source says it is resolved or historical.
   */
  status: 'active' | 'resolved';
  /** When the condition began, at the precision the source knows. Omit if the source does not say. */
  onset?: { value: PartialDate; precision: 'year' | 'month' | 'day' };
  /**
   * For chronic kidney disease only: the KDIGO GFR category the source most recently recorded for this
   * patient ('G3a' for "stage 3a", "N18.31" or a G3a category field). As recorded by a clinician; never
   * computed from lab values.
   */
  ckd_stage?: 'G1' | 'G2' | 'G3a' | 'G3b' | 'G4' | 'G5';
  /** For chronic kidney disease only: KDIGO albuminuria category as recorded ('A1', 'A2', 'A3'), if the source records one. */
  albuminuria?: 'A1' | 'A2' | 'A3';
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Allergies, intolerances, adverse reactions
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One substance the patient should avoid or be careful with, as of `asOf`. Only current entries: an
 * entry the source marks inactive or invalid is not reported. "No known drug allergies" is not a row.
 */
export interface AllergyIntoleranceRow {
  /** Substance: generic ingredient name, lower case, for drugs ("lisinopril"); as written otherwise. */
  substance: string;
  /** RxNorm ingredient CUI, if the source gives one. */
  rxnorm_ingredient?: string;
  /**
   * What kind of reaction, by its nature (not by which list the source keeps it on):
   * - 'allergy': immune-mediated (hives, rash, angioedema, anaphylaxis, bronchospasm).
   * - 'intolerance': a non-immune, predictable side effect that made the drug unacceptable (e.g.
   *   ACE-inhibitor cough, GI upset).
   * - 'adverse_reaction': a serious harmful event attributed to the drug that is not an allergy (e.g.
   *   drug-associated ketoacidosis, lactic acidosis).
   * If the source keeps all three on one undifferentiated list, decide from the recorded reaction.
   */
  type: 'allergy' | 'intolerance' | 'adverse_reaction';
  /** Reaction(s) as the source words them, joined with "; ". Omit if not recorded. */
  reaction?: string;
  /**
   * Criticality: how dangerous re-exposure is judged to be.
   * - 'high': re-exposure could be serious or life-threatening.
   * - 'low': re-exposure unlikely to cause serious harm.
   * - 'unknown': not assessed or not derivable.
   * A source's "severity" scale is mapped by meaning: mild -> 'low'; severe or life-threatening -> 'high'.
   */
  criticality: 'low' | 'high' | 'unknown';
  /** When the reaction began, at the precision the source knows. */
  onset?: { value: PartialDate; precision: 'year' | 'month' | 'day' };
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Lab results
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Analytes this consumer tracks, with the unit `LabResultRow.value` must be in. Results for other
 * tests are not reported.
 *
 * | analyte         | unit            | notes |
 * |-----------------|-----------------|-------|
 * | creatinine      | mg/dL           | serum |
 * | egfr            | mL/min/1.73m2   | see `egfr_equation` and the eGFR rule below |
 * | potassium       | mmol/L          | |
 * | sodium          | mmol/L          | |
 * | chloride        | mmol/L          | |
 * | bicarbonate     | mmol/L          | total CO2 |
 * | anion_gap       | mmol/L          | |
 * | bun             | mg/dL           | urea nitrogen |
 * | glucose         | mg/dL           | laboratory glucose (serum/plasma); home meter readings are vitals |
 * | a1c             | %               | NGSP |
 * | uacr            | mg/g            | urine albumin/creatinine ratio |
 * | platelets       | 10*3/uL         | thousands per microlitre: 212 000 cells/uL is 212 |
 * | wbc             | 10*3/uL         | thousands per microlitre |
 * | hemoglobin      | g/dL            | |
 * | bhb             | mmol/L          | beta-hydroxybutyrate |
 * | ph              | [pH]            | blood gas pH |
 * | pco2            | mmHg            | |
 * | lipase          | U/L             | |
 * | troponin        | ng/mL           | troponin I |
 * | cholesterol     | mg/dL           | total |
 * | triglycerides   | mg/dL           | |
 * | hdl             | mg/dL           | |
 * | ldl             | mg/dL           | measured or calculated |
 */
export type Analyte =
  | 'creatinine' | 'egfr' | 'potassium' | 'sodium' | 'chloride' | 'bicarbonate' | 'anion_gap' | 'bun'
  | 'glucose' | 'a1c' | 'uacr' | 'platelets' | 'wbc' | 'hemoglobin' | 'bhb' | 'ph' | 'pco2' | 'lipase'
  | 'troponin' | 'cholesterol' | 'triglycerides' | 'hdl' | 'ldl';

/**
 * One valid laboratory result.
 *
 * - One row per result. A result the source shows several times (copies in several documents, a
 *   preliminary and a final copy) is one row, taken from the copy with the most advanced status.
 * - Report only values that stand: leave out results that were withdrawn, invalidated or "corrected
 *   away" by the lab, results of orders voided or entered in error, results not performed, and
 *   superseded copies. A confirmation repeat is a second valid result; keep both.
 * - **eGFR rule.** One eGFR row per eGFR calculation the source reports for a specimen. When the source
 *   reports race-specific variants of one calculation (a value with and one without a race
 *   coefficient), report only the variant without the race coefficient. Report the value as printed
 *   (do not recompute).
 */
export interface LabResultRow {
  analyte: Analyte;
  /** Numeric value in the analyte's unit (see `Analyte`). For a result printed with a comparator (">60", "<0.01"), the number part. */
  value: number;
  /** Set when the printed result has a comparator: ">60" -> value 60, comparator '>'. */
  comparator?: '<' | '>' | '<=' | '>=';
  /** The analyte's unit from the table in `Analyte`, exactly as written there. */
  unit: string;
  /** Specimen collection time, RFC 3339 with offset (any offset; it denotes an instant). */
  collected: string;
  /** 'final' (also for amended or corrected values that stand) or 'preliminary'. */
  status: 'final' | 'preliminary';
  /**
   * For analyte 'egfr' only: the equation the source says it used.
   * - 'ckd-epi-2021': CKD-EPI 2021 (race-free).
   * - 'ckd-epi-2009': CKD-EPI 2009.
   * - 'mdrd': MDRD.
   * - 'unknown': not stated.
   * When a code and a method note disagree, believe the method note.
   */
  egfr_equation?: 'ckd-epi-2021' | 'ckd-epi-2009' | 'mdrd' | 'unknown';
  /** LOINC code if the source gives one for this result. */
  loinc?: string;
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Vital signs and home readings
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One set of vital signs taken together, or one home reading.
 *
 * - A clinic or hospital vital-sign set (BP, pulse, weight taken within a few minutes at one visit) is
 *   one row; `local_time` is the time of its first blood pressure (or of its first measurement if no
 *   BP). A repeat blood pressure taken later in the same visit goes in `repeat_*` on the same row.
 * - Each home BP reading and each home glucose reading is its own row.
 * - Each measurement is reported once: if a source shows the same measurement twice (a reading typed
 *   in by hand that duplicates one synced from the device a minute or two earlier with the same
 *   values), report it once, preferring the device copy.
 */
export interface VitalRow {
  /** 'clinic' (outpatient office), 'hospital' (ED or inpatient), or 'home' (patient's own devices). */
  setting: 'clinic' | 'hospital' | 'home';
  /** Local wall-clock time in America/Chicago, `YYYY-MM-DDTHH:MM`. */
  local_time: string;
  systolic_mmhg?: number;
  diastolic_mmhg?: number;
  /** Repeat blood pressure at the same visit, if one was taken. */
  repeat_systolic_mmhg?: number;
  repeat_diastolic_mmhg?: number;
  pulse_bpm?: number;
  /** Body weight in kilograms (1 lb = 0.45359237 kg), one decimal place. */
  weight_kg?: number;
  /** Home glucose meter reading in mg/dL (1 mmol/L = 18.016 mg/dL), rounded to a whole number. */
  glucose_mg_dl?: number;
  /** Set when the meter showed HI or LO instead of a number; `glucose_mg_dl` is then the meter's limit in mg/dL. */
  glucose_out_of_range?: 'HI' | 'LO';
  evidence: Evidence;
}

/**
 * Lakeview Labs & Kidney Care: FOLIO export, version 1.
 *
 * Lakeview runs an outreach reference laboratory and a nephrology clinic on one system. The export is a
 * row-for-row copy of that system's tables. Every payload entry is one table row; its `type` is the table
 * name. Column names are the database's own (UPPER_SNAKE). Codes are Lakeview's, documented below; the
 * tables at the end of this file list every code value in use.
 *
 * Two kinds of item, each with its own entry type:
 *
 * - **Lab report items** (`LabReportRow`): one item per requisition, i.e. one set of specimens drawn at
 *   one time for one ordering client. Holds exactly one LAB_REQ row, one LAB_ORDER row per ordered test,
 *   and the LAB_RESULT rows those orders produced. Published when every order on the requisition is
 *   resulted, cancelled or void (rarely earlier, with 'P' rows, when a slow test holds up a requisition
 *   with urgent results). Lab items have no author (system-generated) and no narrative.
 * - **Clinic contact items** (`ClinicRow`): one item per nephrology clinic contact (office visit or
 *   telephone contact). Holds exactly one CLINIC_VISIT row plus the VISIT_DX, VITAL, MED_ORDER and
 *   MED_STATUS_HIST rows entered during that contact. The narrative is the note the nephrologist typed
 *   and signed; it is short and is never generated from the rows.
 *
 * Changes: rows are never edited in place in the export. When a row changes after its item was
 * published (a result invalidated, an order marked entered in error), Lakeview publishes a new item that
 * `supersedes` the old one and restates every row of the requisition or contact with current values.
 * Exception: a medication's status changes are separate MED_STATUS_HIST rows in a later contact, not a
 * re-published MED_ORDER row. See MED_ORDER.MED_STATUS.
 *
 * Times: every timestamp column is RFC 3339 with the UTC offset in effect in America/Chicago at that
 * moment (e.g. `2026-02-09T08:14:00-06:00`). Date-only columns are local calendar dates.
 *
 * Identifiers: REQ_ID, ORDER_ID, RESULT_ID, ACCESSION, VISIT_ID, RX_ID and HIST_ID are Lakeview-assigned,
 * never reused, and unique across the whole export (not only within an item). Rows refer to rows in
 * other items by these ids.
 */

// ─────────────────────────────────────────────────────────────────────────────────────────────────────
// Lab report items
// ─────────────────────────────────────────────────────────────────────────────────────────────────────

/** One row in a lab report item. */
export type LabReportRow = LabReq | LabOrder | LabResult;

/** The requisition: who ordered, when the specimens were drawn. Exactly one per lab report item. */
export interface LabReq {
  type: 'LAB_REQ';

  /** Requisition id, e.g. "RQ-2602090412". */
  REQ_ID: string;

  /**
   * Ordering client account code. Clients are practices that send work to Lakeview.
   * - 'NGFM': Northgate Family Medicine (outside primary care practice).
   * - 'LVNEPH': Lakeview's own nephrology clinic.
   * Other client codes exist for other patients; CLIENT_NAME always carries the display name.
   */
  CLIENT_CODE: string;

  /** Display name of the ordering client, as on the requisition. */
  CLIENT_NAME: string;

  /** NPI of the ordering clinician, 10 digits. Absent when the requisition was standing-order only. */
  ORDERING_NPI?: string;

  /** Ordering clinician's name, "Last, First Credential", as typed on the requisition. */
  ORDERING_NAME?: string;

  /**
   * When the specimens were drawn. This is the clinically meaningful time and the item's `effective`.
   * All specimens on one requisition share it.
   */
  COLLECTED_AT: string;

  /** When the specimens were logged in at the laboratory. */
  RECEIVED_AT: string;

  /**
   * Patient-reported fasting status at draw.
   * - 'Y': fasting at least 8 hours.
   * - 'N': not fasting.
   * - 'U': not asked or not recorded.
   */
  FASTING: 'Y' | 'N' | 'U';
}

/**
 * One ordered test or panel on the requisition. One row per order, even when two orders are run on the
 * same tube (they then share an ACCESSION).
 */
export interface LabOrder {
  type: 'LAB_ORDER';

  /** Order id, e.g. "OR-7730412". */
  ORDER_ID: string;

  /** The LAB_REQ this order belongs to (always the LAB_REQ in the same item). */
  REQ_ID: string;

  /**
   * What was ordered: a Lakeview test code (see `LabTestCode` at the end of this file). An order code
   * may produce several result rows: panel codes (e.g. 'LK-CBC') produce one row per component, and
   * 'LK-CREAT' also produces calculated eGFR rows.
   */
  ORDER_CODE: `${LabTestCode}`;

  /** Display name of the ordered test as printed on the requisition. */
  ORDER_NAME: string;

  /**
   * Specimen container barcode, "LV" + 2-digit year, day of year, 5-digit sequence, e.g. "LV26-040-00093".
   * One accession per tube; several orders can share one. Outside systems that receive Lakeview results
   * (e.g. Northgate) keep this number as their link back to Lakeview.
   */
  ACCESSION: string;

  /**
   * Specimen type.
   * - 'SER': serum.
   * - 'PLA': plasma (lithium heparin).
   * - 'WB': whole blood (EDTA).
   * - 'URN': random urine.
   */
  SPECIMEN_TYPE: 'SER' | 'PLA' | 'WB' | 'URN';

  /**
   * Specimen condition noted on receipt or by the analyzer.
   * - 'OK': acceptable.
   * - 'HEM': hemolyzed. Potassium, AST and LDH can be falsely high. Results are still released, with a
   *   comment; a recollection is usually requested.
   * - 'LIP': lipemic.
   * - 'ICT': icteric.
   * - 'QNS': quantity not sufficient; affected results have RESULT_STATUS 'X'.
   * - 'CLT': clotted.
   */
  SPECIMEN_COND: 'OK' | 'HEM' | 'LIP' | 'ICT' | 'QNS' | 'CLT';

  /**
   * Where the order stands in the lab workflow. Integer code. This is a separate axis from each result
   * row's RESULT_STATUS: an order is 4 (resulted) as soon as its results have been released, and stays 4
   * even if one of its results is later invalidated (RESULT_STATUS 'C'). Never infer result validity from
   * this field.
   * - 1: ordered, not yet collected.
   * - 2: collected, in transit or awaiting testing.
   * - 3: in process (some results may be preliminary).
   * - 4: resulted (results released).
   * - 5: cancelled before testing (no results; see STATUS_REASON).
   * - 9: entered in error (wrong patient, duplicate order). The order is void. Any result rows it has
   *      were produced by the analyzer before the error was caught, still carry their own
   *      RESULT_STATUS (often 'F'), and must not be used.
   */
  ORDER_STATUS: 1 | 2 | 3 | 4 | 5 | 9;

  /** When ORDER_STATUS last changed. */
  STATUS_AT: string;

  /** Free-text reason entered with status 5 or 9, e.g. "Duplicate order". Absent for other statuses. */
  STATUS_REASON?: string;

  /**
   * Set when this order is a repeat draw of an earlier order (in an earlier requisition): that order's
   * ORDER_ID. Absent for ordinary orders.
   */
  REPEAT_OF_ORDER_ID?: string;

  /**
   * Why the repeat draw was taken. Present exactly when REPEAT_OF_ORDER_ID is.
   * - 'HEM': the earlier specimen was hemolyzed. The earlier result is normally invalidated
   *   (RESULT_STATUS 'C', REPLACED_BY_RESULT_ID pointing here).
   * - 'CONF': confirmation of a critical or unexpected value. Both results stand; the earlier one is
   *   NOT invalidated.
   * - 'QNS': the earlier specimen was insufficient.
   */
  REPEAT_REASON?: 'HEM' | 'CONF' | 'QNS';
}

/**
 * One reported result value. Lakeview stores every result as text (VALUE_TEXT) plus a numeric
 * convenience column (VALUE_NUM). VALUE_TEXT is the value of record.
 */
export interface LabResult {
  type: 'LAB_RESULT';

  /** Result id, e.g. "RS-90044817". */
  RESULT_ID: string;

  /** The LAB_ORDER that produced this row (always in the same item). */
  ORDER_ID: string;

  /**
   * Lakeview test code for this result (see `LabTestCode`). Codes are stable across years but are
   * retired and replaced when the method or equation changes: eGFR changed code on 2022-01-10. A
   * mapper that needs a continuous series must join the old and new codes.
   */
  TEST_CODE: `${LabTestCode}`;

  /** Test name as printed on the report on the day it was resulted. Wording varies over the years. */
  TEST_NAME: string;

  /**
   * LOINC code, copied from Lakeview's code table at the moment the row was resulted. Absent when the
   * test code had no LOINC mapping at that moment, which includes some codes that are mapped now (rows
   * resulted before the mapping was added are not back-filled). `LabTestCode` says which codes
   * have a mapping and since when. Do not use LOINC as the only key to find a test; use TEST_CODE.
   */
  LOINC?: string;

  /**
   * The result as reported, as text. Usually a plain decimal ("1.45", "212"). May carry a comparator
   * (">60", "<0.1", ">90") or be non-numeric ("Not done: QNS", "See comment"). Never sort or compare as
   * text.
   */
  VALUE_TEXT: string;

  /**
   * Numeric form of VALUE_TEXT, for queries.
   * - A number when VALUE_TEXT is a plain decimal: the same value.
   * - 9999999 (sentinel) when VALUE_TEXT has a comparator such as ">60": the number is NOT the value;
   *   read VALUE_TEXT.
   * - null when VALUE_TEXT is not numeric.
   */
  VALUE_NUM: number | null;

  /**
   * Unit of VALUE_TEXT, as Lakeview prints it (see `LakeviewUnit`). Fixed per TEST_CODE. Null only when
   * VALUE_TEXT is not numeric. Note 'K/uL' means thousands per microlitre: a platelet count of "212" is
   * 212 000 cells/uL.
   */
  UNIT_CODE: `${LakeviewUnit}` | null;

  /** Reference interval as printed, e.g. "3.5-5.1", "<30", ">59". Text; may be absent for calculated tests. */
  REF_RANGE_TEXT?: string;

  /**
   * Abnormal flag against the reference interval.
   * - 'N': within range.
   * - 'L' / 'H': below / above range.
   * - 'LL' / 'HH': critical low / high (phoned to the ordering clinician).
   * - 'A': abnormal, non-numeric.
   * Absent when the test has no reference interval or the value is not numeric.
   */
  ABN_FLAG?: 'N' | 'L' | 'H' | 'LL' | 'HH' | 'A';

  /**
   * Validity of this row's value. Letter code. Independent of the order's ORDER_STATUS.
   * - 'P': preliminary; a later item will restate the row as 'F'.
   * - 'F': final.
   * - 'A': amended; the value on this row was changed after it was final (for example a transcription
   *   fix). The value shown is the current, valid one; the earlier value is in the superseded item.
   * - 'C': corrected away. The value on this row has been withdrawn and must not be used. If a
   *   replacement exists, REPLACED_BY_RESULT_ID names it (usually in a repeat-draw requisition). Note:
   *   this is NOT the HL7 v2 meaning of 'C' (where 'C' marks the new corrected value); in Lakeview 'C'
   *   marks the old, withdrawn one.
   * - 'X': not performed (cancelled, QNS); VALUE_TEXT says why, VALUE_NUM is null.
   */
  RESULT_STATUS: 'P' | 'F' | 'A' | 'C' | 'X';

  /** When the value was released (first released, for 'A' and 'C' rows). */
  RESULTED_AT: string;

  /** When RESULT_STATUS was set to 'A' or 'C'. Absent otherwise. */
  STATUS_CHANGED_AT?: string;

  /** For RESULT_STATUS 'C': the RESULT_ID of the row that replaces this one. Absent if no replacement. */
  REPLACED_BY_RESULT_ID?: string;

  /**
   * For calculated results: the RESULT_ID of the row it was calculated from (same item): the
   * creatinine row for eGFR, the total cholesterol row for calculated LDL (LK-LDLC).
   * Lakeview calculates eGFR from creatinine, the patient's age and sex on the collection date, and,
   * for the 2009 codes only, a race coefficient (both race variants are always reported; the lab
   * does not know the patient's race).
   */
  DERIVED_FROM_RESULT_ID?: string;

  /** Result comment as printed on the report, free text. Lakeview's comments are canned phrases. */
  COMMENT_TEXT?: string;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────────
// Clinic contact items
// ─────────────────────────────────────────────────────────────────────────────────────────────────────

/** One row in a nephrology clinic contact item. */
export type ClinicRow = ClinicVisit | VisitDx | Vital | MedOrder | MedStatusHist;

/** The clinic contact itself. Exactly one per clinic contact item. */
export interface ClinicVisit {
  type: 'CLINIC_VISIT';

  /** Contact id, e.g. "NV-104552". */
  VISIT_ID: string;

  /**
   * Kind of contact.
   * - 'NP': new patient office visit.
   * - 'FU': follow-up office visit.
   * - 'TEL': telephone contact (no vitals; CKD_G / CKD_A usually absent).
   */
  VISIT_TYPE: 'NP' | 'FU' | 'TEL';

  /** Start of the contact. The item's `effective`. */
  VISIT_AT: string;

  /** NPI of the nephrologist responsible for the contact. */
  PROVIDER_NPI: string;

  /**
   * KDIGO GFR category as assessed by the nephrologist at this contact: 'G1', 'G2', 'G3a', 'G3b',
   * 'G4', 'G5'. A clinician judgement (usually from two or more eGFRs ≥ 90 days apart), not computed
   * from a single lab value. Absent when not assessed at this contact.
   */
  CKD_G?: 'G1' | 'G2' | 'G3a' | 'G3b' | 'G4' | 'G5';

  /**
   * KDIGO albuminuria category as assessed at this contact: 'A1' (UACR < 30 mg/g), 'A2' (30–300),
   * 'A3' (> 300). Absent when not assessed.
   */
  CKD_A?: 'A1' | 'A2' | 'A3';

  /** Referring practice as typed at registration, free text. Present on 'NP' visits from a referral. */
  REFERRED_BY_TEXT?: string;
}

/** One diagnosis recorded at the contact. The clinic's problem list is the latest VISIT_DX row per code. */
export interface VisitDx {
  type: 'VISIT_DX';

  /** The contact (same item). */
  VISIT_ID: string;

  /** Order of importance at this contact, 1 = primary. */
  DX_RANK: number;

  /** ICD-10-CM code, with the dot (e.g. "N18.32"). Always present. */
  ICD10CM: string;

  /** ICD-10-CM description as shown in the clinic system. */
  DX_TEXT: string;

  /**
   * - 'A': active, confirmed.
   * - 'P': provisional / working diagnosis.
   * - 'R': ruled out at this contact. Not a diagnosis the patient has.
   * - 'H': history of; resolved, recorded for context.
   */
  DX_STATUS: 'A' | 'P' | 'R' | 'H';
}

/**
 * One vital-sign measurement taken at an office visit. Blood pressure is two rows (systolic and
 * diastolic) linked by READING_NO. Unlike lab values, vitals are stored as numbers.
 */
export interface Vital {
  type: 'VITAL';

  /** The contact (same item). */
  VISIT_ID: string;

  /**
   * - 'BPS': systolic blood pressure, mmHg.
   * - 'BPD': diastolic blood pressure, mmHg.
   * - 'HR': heart rate, /min.
   * - 'WT': weight, kg.
   */
  VITAL_CODE: 'BPS' | 'BPD' | 'HR' | 'WT';

  /** The measurement, in UNIT_CODE. */
  VALUE_NUM: number;

  /** 'mmHg' for BPS/BPD, '/min' for HR, 'kg' for WT. Always present. */
  UNIT_CODE: 'mmHg' | '/min' | 'kg';

  /** 1 for the first reading of this VITAL_CODE at the contact, 2 for a repeat, and so on. */
  READING_NO: number;

  /** When the measurement was taken. */
  TAKEN_AT: string;
}

/**
 * A medication prescribed or managed by the nephrology clinic, as the row stood when this item was
 * published. The clinic records only medications it prescribes or changes; it does not keep a full home
 * medication list.
 */
export interface MedOrder {
  type: 'MED_ORDER';

  /** Prescription id, e.g. "RX-30418". Stable for the life of the prescription. */
  RX_ID: string;

  /** The contact at which it was prescribed (same item). */
  VISIT_ID: string;

  /** Lakeview formulary id, e.g. "LVD-04471". Always present; stable across years. */
  LV_DRUG_ID: string;

  /** Drug name and strength from the Lakeview formulary, e.g. "finerenone 10 mg tablet". */
  DRUG_NAME: string;

  /**
   * RxNorm CUI (SCD or SBD) from the formulary. Absent for drugs added to the formulary locally without
   * a mapping; recent additions often have none. Identify the drug by LV_DRUG_ID and DRUG_NAME.
   */
  RXNORM?: string;

  /** Dose per administration, as a number. */
  DOSE_QTY: number;

  /** Unit of DOSE_QTY: 'mg', 'mcg', 'unit', 'mL'. */
  DOSE_UNIT: 'mg' | 'mcg' | 'unit' | 'mL';

  /** 'PO' by mouth, 'SC' subcutaneous, 'IV' intravenous. */
